{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Isradipine, a lipophilic dihydropyridine with extensive first-pass metabolism, had mean systemic availability of 16.5% in healthy volunteers, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pentazocine absolute oral bioavailability was 18.5% in a healthy subject after tablet dosing, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Nifedipine absolute bioavailability was 0.43 ± 0.14 after oral tablets, above the 20% threshold, but nifedipine is a much smaller, well-absorbed dihydropyridine and is not structurally analogous to the long-chain ubiquinone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is ubiquinone-10 (coenzyme Q10), a high-molecular-weight, highly lipophilic benzoquinone with established poor and variable oral absorption. Low-F analogs such as isradipine and pentazocine support a below-20% outcome, while high-F records are not structurally transferable. Therefore the prediction is low.",
  "evidence_gaps": [
    "No direct experimental record for ubiquinone-10/CoQ10 is present in the provided evidence set.",
    "Absolute oral bioavailability of CoQ10 in humans is not directly measured in these records and is formulation-dependent.",
    "Most analog records are small-molecule drugs whose low F is driven by first-pass metabolism rather than the poor dissolution/absorption expected for the large lipophilic quinone."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

